import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).trim();
        // Adjacent runs of lengths p and q give min(p, q) valid substrings.
        long prev = 0, cur = 1, ans = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) cur++;
            else { ans += Math.min(prev, cur); prev = cur; cur = 1; }
        }
        ans += Math.min(prev, cur);
        System.out.println(ans);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	s := strings.TrimSpace(string(data))
	// Adjacent runs of lengths p and q give min(p, q) valid substrings.
	var prev, cur, ans int64 = 0, 1, 0
	for i := 1; i < len(s); i++ {
		if s[i] == s[i-1] {
			cur++
		} else {
			ans += min(prev, cur)
			prev, cur = cur, 1
		}
	}
	ans += min(prev, cur)
	fmt.Println(ans)
}
